const detail = (title, body) => `<details class="chapter-details"><summary>${title}<span>+</span></summary><div>${body}</div></details>`;
const list = items => `<ul class="plain-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const note = (label,text) => `<div class="editorial-note"><strong>${label}</strong><p>${text}</p></div>`;
const demo = (id,label='Existing MathConcept demo') => `<div class="demo-wrap"><div class="demo-caption"><span>${label}</span><span>${id==='rollout'?'Proposed delivery sequence':'Separate proposal session'}</span></div><div class="demo" data-demo="${id}" id="demo-${id}"></div></div>`;
const proposedFlow = (label,steps,text) => `<div class="proposed-flow"><span class="field-label">${label}</span><ol>${steps.map(step=>`<li>${step}</li>`).join('')}</ol><p>${text}</p></div>`;
export const chapters = [
 {id:'vision',title:'The proposal'},
 {id:'system',title:'One connected system',kicker:'A shared operating model',heading:'From HQ’s curriculum<br>to a student’s next lesson.',intro:'Each role sees the tools and information it needs. The work connects through the same students, lessons and approved materials.',body:demo('system')+detail('How the roles connect',list(['HQ authors and approves the curriculum, manages access and sets centre policies.','Centre staff manage enrolment, schedules, parent requests and billing.','Teachers select students from their classes, assign work and review learning.','Students work in their binder; parents handle practical arrangements through a separate app.','Every assignment points to a specific published worksheet version. Access to an answer key is checked separately.']))+note('One system, distinct responsibilities','Explore the existing Admin, Teacher, Parent and Student interfaces. HQ publishing, curriculum permissions and production integrations are proposed extensions.')},
 {id:'protection',title:'Protect the curriculum',kicker:'Controlled distribution',heading:'Keep the originals private.<br>Make teaching access easy.',intro:'Replace direct shared-drive access with a controlled library. Distribute the material needed for teaching, with an accountable route to screens and printers.',body:proposedFlow('Proposed access & printing workflow',['Private originals','Approved pages','Authorised view or print','Issue record'],'HQ keeps the source files. Approved page views and print jobs follow the account, centre and assignment permissions. Controlled printing and copy identifiers remain proposed features.')+`<div class="three-columns"><article><h3>Access by role</h3><p>HQ manages originals. Centres see their permitted curriculum. Students see assigned work.</p></article><article><h3>Authorised printing</h3><p>Approved jobs go to a managed device and printer, with limits and an activity record.</p></article><article><h3>Traceable copies</h3><p>An issue reference connects a copy to its worksheet version, centre, account and print job.</p></article></div>`+detail('Controls, limits and validation',list(['Keep original PDFs and authoring files in private storage. Deliver authorised page representations where originals must remain private.','A managed print connector and printer still process print data. Storage, spool cleanup, administration and failed jobs need explicit controls.','A proposed subtle dot pattern would supplement the readable issue reference. Recovery from scans, photos and photocopies must be tested before any performance claim.','Viewing and printing permit screenshots, photography and later copying. These controls reduce easy bulk extraction and support investigation; they cannot prevent every leak.','A recovered reference identifies the issued copy. It does not prove which individual leaked it.','Offboarding must revoke centre and account access. Previously photographed or printed content cannot be recalled.']))},
 {id:'library',title:'Use the existing library',kicker:'Preserve, organise, upgrade',heading:'Bring 200,000+ files forward.<br>Keep their teaching value.',intro:'Make the existing collection searchable and assignable, then progressively turn priority materials into reusable, editable questions.',body:demo('library','Curriculum catalogue & assignment')+note('Existing catalogue','The demo uses the supplied curriculum indexes. P3 and P6 include sample questions; original worksheet files and editable conversion are still to be connected.')+`<div class="three-columns numbered"><article><span>01</span><h3>Preserved pages</h3><p>Retain the original layout. Add search, controlled access and a digital writing surface.</p></article><article><span>02</span><h3>Reusable questions</h3><p>Select a question and its diagram from an existing page. Reuse it with its source recorded.</p></article><article><span>03</span><h3>Editable content</h3><p>Verify extracted text, equations and answers before publishing a native question.</p></article></div>`+detail('Migration scope and quality checks',list(['Inventory actual formats, page counts, file health and folder structure before estimating conversion effort. File count does not equal question count.','Preserve a read-only master, original path, stable reference and version relationships. Identify exact duplicates separately from revised editions.','Map approved worksheet codes to the teacher’s progress chart, including grades, topics and collections.','Search recognition may contain errors; the faithful page remains the teaching reference until an extracted version is checked.','Check decimal points, fractions, units, diagrams, subquestions and answer-key alignment. Preserve difficult questions as images until verified.','Measure full-library coverage separately from the count of verified, editable questions. Library migration and structured conversion are separate delivery scopes.']))},
 {id:'authoring',title:'Create new materials',kicker:'Digital-first authoring',heading:'A worksheet studio<br>built for the way maths is taught.',intro:'Assemble approved questions, create new ones and add enough room to think. Use the same content for portrait tablets and carefully paginated print.',body:proposedFlow('Proposed authoring workflow',['Create or select questions','Review answers and layout','Publish a version'],'Assemble approved questions and new content, then publish a reviewed version for teachers to assign. Native authoring and AI assistance are not yet part of the existing demo.')+`<div class="two-columns"><article><h3>Content with structure</h3><p>A question has its own prompt, mathematical notation, assets, answer, marking guidance, curriculum tags and version. A worksheet brings those questions together.</p></article><article><h3>AI with an editorial process</h3><p>AI can find examples, draft variants and assist conversion. Authors review the questions, answers and layout before publication.</p></article></div>`+detail('Authoring and AI delivery scope',list(['Start with rich text, equations, images, reusable questions, answer fields and handwriting space. Add specialised interactive diagrams by curriculum priority.','AI-generated content remains a draft. Use calculation checks for suitable question families and human review for meaning, difficulty, diagrams and worked solutions.','AI processing must follow the agreed content permissions and approved provider or private-processing arrangement. The proposal does not grant permission to upload the library to an external AI service.','Keep answers and teacher notes out of student responses, search results and exports. Hiding them visually is insufficient.','Provide both tablet and A4 previews. Page breaks, working space and keeping question parts together are explicit publishing checks.','Published assignments retain their version. Editing the library creates a new version instead of changing work already issued.']))},
 {id:'teacher',title:'The teacher workbench',kicker:'Prepare and teach',heading:'The progress chart<br>becomes the workbench.',intro:'Choose a class, select a student and send the right worksheets directly. Their grade is the starting point; teachers can browse other levels when appropriate.',body:demo('teacher')+note('Connected example','Choose worksheets, select “Send to student”, then “View student app” to open that student’s binder. “Prepare for later” keeps work locked until the teacher releases it.')+detail('Teaching workflow',list(['Keep classes and students in a narrow side strip, grouped by the teacher’s actual teaching sessions.','Show worksheet collections together in the progress chart. Use grade, topic and worksheet-code navigation.','Distinguish assignment, student progress, work awaiting marking and corrections. Staff can inspect the underlying work.','Teachers can select classwork or homework and issue approved worksheet versions. Future work stays locked until released.','Handwritten working, marking and corrections remain attached to the original question and assignment version.']))},
 {id:'student',title:'The student workspace',kicker:'A familiar binder, made digital',heading:'More room for working.<br>Less interface to think about.',intro:'Three familiar places: work to do now, work already completed and work the teacher has prepared for later. Prioritise portrait tablets and the writing surface.',body:demo('student')+detail('Student experience and devices',list(['Current work includes corrections from a previous lesson. Completed work remains available for review.','Future work cannot be opened by students until the teacher releases it. Access is enforced beyond the interface.','Keep controls compact and allow a full-screen writing surface. Parent and student interfaces use Hong Kong Traditional Chinese.','Preserve strokes against stable page or question coordinates. Layout changes must not move a child’s working to the wrong question.','Validate stylus behaviour, palm rejection, save/reconnect handling and supported devices during the pilot. Offline requirements need a deliberate policy and scope.','Automatic marking is limited to validated question types. Handwritten reasoning and method marks continue to support teacher review.']))},
 {id:'operations',title:'Centre & parent coordination',kicker:'Keep arrangements clear',heading:'A schedule staff can trust.<br>A clear next step for parents.',intro:'Leave is recorded promptly. Staff arrange the replacement lesson with the parent. Temporary and permanent changes show their lesson-count impact before confirmation.',body:demo('operations')+`<div class="two-columns"><article><h3>Parents request leave</h3><p>The app confirms leave and invites optional preferred dates. It clearly says CS will contact the parent to finish the make-up arrangement.</p></article><article><h3>Staff confirm arrangements</h3><p>The cancelled lesson is crossed out and appears in the leave bin. A make-up is scheduled only when staff confirm the agreed time.</p></article></div>`+detail('Schedule rules and communication',list(['Allow staff to drag lessons into a new slot or into the leave bin, with a keyboard-accessible way to make the same selection.','Show each teacher’s availability with a light-grey treatment for unavailable times. Validate capacity, availability and clashes before confirming changes.','Support a change-from date and an optional final date. After a temporary change ends, the original regular schedule resumes.','Compare the affected lessons: an increase requires an explicit decision about the extra lesson; a reduction requires a decision about a make-up credit.','Keep receipt and schedule amendments linked, with an audit trail and the original records retained. The final document revision and date policy needs agreement.','Student information includes remaining lesson dates. Parent communication and lesson remarks stay connected to the relevant student and lesson.']))},
 {id:'billing',title:'Payments & final audit',kicker:'Make the next action obvious',heading:'Know what needs attention.<br>Close the loop with the bank.',intro:'Follow each invoice through parent payment, centre review and receipt issuance. Reconcile issued receipts against bank records in a separate final audit.',body:demo('billing')+note('Receipt issuance and reconciliation are separate','The proposed “Auto-sent” policy issues a receipt after payment proof passes agreed checks. It does not mean the money has been matched to the bank. Manual review remains an alternative; final audit identifies differences.')+detail('Billing rules and exceptions',list(['One row represents one invoice. A student may have an older unpaid invoice, another awaiting review and a completed invoice at the same time.','Default to the centre-review queue. Show deadlines and overdue bills, oldest proofs first, and newest receipts first.','Search by student name, student number or invoice number; filter by charge type and optional billing month. Production lists request only the current page, around 25 rows.','Review the invoice beside the payment proof without leaving the filtered list. Confirmation issues the receipt; returning proof requires a reason and asks for replacement evidence, not another payment.','Keep review open if saving fails. Track reminders and prevent repeats within 24 hours. Archive cancelled and void invoices separately.','“Auto-sent” is the centre’s proposed default. Failed or uncertain proof checks go to review. These checks are simulated in this proposal and require validation in production.','Import statement transactions once, prevent a credit from being allocated twice, and flag missing, extra or ambiguous matches. Keep initiation, proof submission, receipt issue and bank posting dates distinct.','Cash, cheques, combined payments, partial payments and refunds need their own agreed handling. Direct bank API integration is optional and unconfirmed; statement import is the baseline.']))},
 {id:'franchise',title:'Operate across centres',kicker:'Grow with consistent control',heading:'HQ sets the standards.<br>Centres run the day.',intro:'Give each franchise the curriculum and operating tools it needs, with clear boundaries and central ownership of publishing and access policies.',body:demo('franchise','Tsuen Wan & Hang Hau')+note('Shared application','Both centres use the same application, with their own identity, teachers and demo records. HQ permissions and network reporting are proposed extensions.')+detail('Network governance',list(['Separate centre data and permitted curricula. Switching a visible centre selector must never bypass server-side authorisation.','HQ controls publication, versions and curriculum entitlements. Local teaching and operational permissions are configurable within an agreed role model.','Track unusual access or print volume against agreed thresholds, with a process for review rather than automatic accusations.','Provide centre-level visibility into unresolved scheduling and payment work. Reporting definitions must be agreed before comparison across centres.','Plan onboarding, staff changes, franchise offboarding, support coverage and language requirements as part of expansion.','HQ retains ownership of supplied curriculum and operational data. The agreement defines software ownership, licensing, export and handover arrangements.']))},
 {id:'rollout',title:'Migration, pilot & rollout',kicker:'Prove the workflow, then expand',heading:'Start with one centre.<br>Build evidence for the next.',intro:'Validate real materials, devices and staff routines before expanding. Each stage ends with an agreed decision based on results.',body:demo('rollout','Delivery roadmap')+`<div class="two-columns responsibility"><article><h3>MathConcept provides</h3><p>Authorised materials and source data, curriculum and operations owners, representative exceptions, pilot users and timely review decisions.</p></article><article><h3>The delivery team provides</h3><p>Agreed design and implementation, migration tooling, validation reports, staff training, documentation and release support.</p></article></div>`+detail('Pilot acceptance examples',list(['A teacher can find the correct approved worksheet, assign it and review the student’s saved work on the agreed device.','A student can resume saved work after an agreed interruption scenario without lost or misplaced handwriting.','A parent leave request updates the original lesson and staff queue without automatically confirming a replacement time.','An invoice follows the agreed manual or automatic receipt policy; statement import flags unexplained differences and duplicate allocations.','An unauthorised centre cannot retrieve original files, another centre’s student records or restricted answer keys.','An approved print job is logged and behaves correctly on success, failure and retry. Watermark recovery is measured separately under agreed capture conditions.','Migration samples preserve the required equations and layout; exceptions are reported and resolved or retained in faithful page form.']))},
 {id:'proposal',title:'Scope, investment & next steps',kicker:'A clear basis for delivery',heading:'Agree the first release.<br>Make the next decision concrete.',intro:'This first draft defines the direction and gives the workflows something tangible to respond to. Scope, price and delivery dates follow validation of the library, operating rules and pilot requirements.',body:`<div class="scope-matrix"><article><span class="scope-label">FOUNDATION</span><h3>Proposed first release</h3><p>Controlled library, teacher assignment, student binder, centre and parent workflows, invoice queues and statement reconciliation for the agreed pilot.</p></article><article><span class="scope-label">STAGED DEVELOPMENT</span><h3>Authoring & expansion</h3><p>Native worksheet creation, verified question conversion, selected AI assistance, richer reporting and a managed rollout to more centres.</p></article><article><span class="scope-label">FEASIBILITY CHECKS</span><h3>Validate before committing</h3><p>Bulk conversion quality, print-device support, handwriting behaviour, covert watermark recovery, bank APIs and additional payment methods.</p></article></div><div class="commercial-panel"><div><span class="eyebrow">COMMERCIAL BASIS</span><h3>Separate the investment into clear parts.</h3></div><div class="cost-lines"><div><span>Platform design & implementation</span><strong>To be scoped</strong></div><div><span>Library migration & editable conversion</span><strong>Quoted separately</strong></div><div><span>Hosting, storage & third-party services</span><strong>Usage assumptions required</strong></div><div><span>Support, maintenance & training</span><strong>Service terms to agree</strong></div></div></div><div class="decision-box"><span>THE NEXT DECISION</span><h3>Agree a representative pilot and its success measures.</h3><p>Confirm the participating centre, material sample, device and printer setup, decision owners and priority workflows. Then turn the agreed scope into a delivery plan and commercial proposal.</p><div class="button-row"><button class="primary-button" data-action="reference" data-ref="scope">Read the detailed scope <span>↗</span></button><button class="secondary-button" data-action="reference" data-ref="assumptions">Review open decisions</button></div></div>`+detail('Ownership, support and handover',list(['MathConcept retains ownership of its supplied curriculum and operational data. Define ownership and licensing of new software and new content in the agreement.','Agree hosting responsibility, authorised administration, backup and restore arrangements, data export and handover provisions.','Define support hours, incident handling, update responsibilities, security maintenance and third-party service dependencies.','Costs and timelines shown in a later commercial proposal must be based on validated scope. No implementation price or delivery date is committed in this draft.']))}
];
export function chapterHTML(c,i){return `<section class="chapter" id="${c.id}" data-chapter="${i}" aria-labelledby="heading-${c.id}"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${c.kicker}</div><div class="chapter-heading"><h2 id="heading-${c.id}">${c.heading}</h2><p class="section-intro">${c.intro}</p></div>${c.body}</section>`}
export const references = {
 scope:{title:'Detailed scope',body:`<p class="reference-lead">A working scope for discussion. “Proposed” items are delivery requirements to validate and agree, not a statement that the production system already exists.</p><h3>Curriculum & content</h3>${list(['Private original-file archive, catalogue, worksheet codes, curriculum mapping, role-scoped search and version history.','Faithful page delivery first; reusable image questions and verified editable questions introduced progressively.','Authoring blocks, equations, images, working space, tablet/A4 previews and review/publish permissions.','AI retrieval, drafting and conversion assistance with approved processing and human publication control.'])}<h3>Teaching & learning</h3>${list(['Classes and students grouped around the teacher’s schedule; grade browsing and progress-chart assignment.','Classwork/homework, current/past/future binder, locked unreleased work, handwritten working, marking and corrections.','Stable assignment versions and explicit device, save/reconnect and offline acceptance criteria.'])}<h3>Centre & parent operations</h3>${list(['Scheduling, teacher availability, lesson remarks, remaining lessons and student information.','Leave confirmation, optional date preferences, staff-arranged make-ups and the leave bin.','Single, temporary and ongoing schedule changes with conflict and lesson-count review.','Parent-facing records and communication attached to the appropriate student and lesson.'])}<h3>Billing</h3>${list(['Invoice lifecycle queues, manual review, optional Auto-sent policy, reminders, receipt records and archive.','Search, charge/month filters and paginated server-backed lists in production.','Bank-statement import, matching suggestions, allocation controls, exception handling and final audit.','Cash, cheque, refunds and combined/partial payments require agreed rules; bank APIs are a separate feasibility item.'])}<h3>HQ & franchises</h3>${list(['Centre separation, curriculum entitlements, role permissions, approval workflows and revocation.','Access/printing records, operational oversight, migration reports, training and support arrangements.'])}<h3>Demonstration boundaries</h3><p>The embedded screens run the existing MathConcept demo. Changes are saved in a separate proposal session in this tab; they do not change the main demo’s saved records or sync across devices. Tsuen Wan timetable names and slots come from supplied schedules; payment and other workflow records are examples. P3 and P6 contain sample questions; other catalogue entries require their original files. Payment checks are simulated. HQ publishing, conversion, native authoring, controlled printing and production access controls remain proposed scope.</p>`},
 technical:{title:'Technical approach & security',body:`<p class="reference-lead">A proposed architecture to validate against the material inventory, expected usage and agreed deployment environment.</p><h3>Three connected content layers</h3>${list(['Originals: private files with a stable ID, checksum, source path and version relationships.','Published material: approved page representations and structured question records with separate teacher solutions.','Assignments: specific published versions, student working and marking records.'])}<h3>Access and delivery</h3><p>Authenticate users and check permissions on the server for every protected resource. Keep answer keys and restricted originals out of student responses. Use controlled page delivery, scoped print jobs and auditable actions. Expiring links alone do not make a downloadable original uncopyable.</p><h3>Reliability</h3><p>Define save/retry behaviour, duplicate-action protection, statement-import idempotency, backups and restore tests. Validate production loads using an agreed model of concurrent classes, page requests, handwriting saves and print jobs; student count alone is not a load test.</p><h3>Document conversion</h3><p>Evaluate recognition tools on representative maths and diagrams. Preserve originals and route uncertain output to review. Existing editor support for equations does not establish faithful document-import support.</p><h3>Traceability</h3><p>A unique per-issue reference maps to private records. A billion copies per worksheet require at least 30 identifier bits when the worksheet is known separately; alignment, error correction and authentication add overhead. A subtle printed pattern requires independent validation and is not guaranteed to survive removal or reconstruction.</p><h3>Interoperability & ownership</h3><p>Keep controlled HQ exports for originals, content records and operational data. Use portable mathematical representations and evaluate QTI-compatible exchange where useful. Export permissions for HQ remain separate from franchise access.</p><h3>Technical references</h3><ul class="source-links"><li><a href="https://docs.mathpix.com/" target="_blank" rel="noopener">Mathpix — STEM recognition and document conversion ↗</a></li><li><a href="https://tiptap.dev/docs/conversion/content-types/structures-and-media/math-equations" target="_blank" rel="noopener">Tiptap — equation editing and import limitations ↗</a></li><li><a href="https://www.1edtech.org/standards/qti/index" target="_blank" rel="noopener">1EdTech — question and test interoperability ↗</a></li><li><a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/using-presigned-url.html" target="_blank" rel="noopener">AWS — scope and limitations of signed download links ↗</a></li><li><a href="https://www.qrcode.com/en/codes/microqr.html" target="_blank" rel="noopener">DENSO WAVE — Micro QR capacity and structure ↗</a></li></ul><p class="small">References support feasibility research. They are not a commitment to a supplier or an accuracy, security or performance guarantee.</p>`},
 assumptions:{title:'Open decisions & responsibilities',body:`<p class="reference-lead">These decisions shape scope and cost. They can be resolved during discovery and the pilot.</p><h3>Materials</h3>${list(['What file formats and page counts exist, and which editions are authoritative?','Which grades and worksheet families should be converted into editable questions first?','Who checks mathematical accuracy, answer keys and publication readiness?','Which external AI/OCR processing arrangements are acceptable?'])}<h3>Teaching and devices</h3>${list(['Which tablets, styluses, browsers, printers and managed connector devices will be supported?','Is offline work required, and how should protected content and unsent work be handled offline?','Which question types need automatic marking, interactive diagrams or manual review?'])}<h3>Operations and finance</h3>${list(['Confirm leave, make-up expiry, schedule-change and extra-lesson rules.','Agree receipt wording and the evidence required by the Auto-sent policy; retain independent bank-reconciliation state.','Confirm bank export formats, matching rules, cash/cheque handling, split payments, refunds and month-end exceptions.','Agree notification channels, message retention and parent communication responsibilities.'])}<h3>Commercial and rollout</h3>${list(['Choose the pilot centre, participant group, representative material sample and decision owners.','Set measurable acceptance criteria and a gate before centre-wide or overseas rollout.','Agree source-data cleanup responsibilities, software licensing/ownership, hosting, support and handover.','Confirm price, implementation schedule and recurring costs after these assumptions are validated.'])}`}
};
